def purge_old_orders(session, days=365):
    cutoff = _cutoff(days)
    removed = _expired_orders(session, cutoff).delete(synchronize_session=False)
    session.commit()
    return {'removed': removed}


def purge_all(session):
    orders = purge_old_orders(session)
    invoices = purge_old_invoices(session)
    return {'orders': orders, 'invoices': invoices}

