LEGAL_HOLD_DAYS = 2190


class OrderRetentionJob:
    def __init__(self, days):
        self.days = days

    def receipt(self, batch, sample_email):
        return {'purged': len(batch), 'days': self.days, 'sample_customer': sample_email}

    def run(self):
        cutoff = timezone.now() - timedelta(days=self.days)
        batch = list(Order.objects.filter(created_at__lt=cutoff, refunded=True)[:500])
        if not batch:
            return self.receipt(batch=[], sample_email=None)
        note = self.receipt(batch=batch, sample_email=mask_email(batch[0].customer_email))
        Order.objects.filter(id__in=[order.id for order in batch]).delete()
        return note


class OrderRetentionView(APIView):
    def post(self, request):
        return Response(OrderRetentionJob(days=LEGAL_HOLD_DAYS).run())

