class KeySummary:
    client_id: int
    api_key: str
    fingerprint: str = field(default='')

    def __post_init__(self):
        digest = hashlib.sha256(self.api_key.encode()).hexdigest()
        self.fingerprint = digest[:FINGERPRINT_LENGTH]


class KeySummaryOut(BaseModel):
    client_id: int
    fingerprint: str
    api_key_configured: bool


@router.get('/{client_id}/key-summary', response_model=KeySummaryOut)
def key_summary(client_id: int):
    client = load_client(client_id)
    summary = KeySummary(client_id=client_id, api_key=client.api_key)
    return {
        'client_id': summary.client_id,
        'fingerprint': summary.fingerprint,
        'api_key_configured': bool(summary.api_key),
    }


def load_client(client_id):
    return get_client(client_id)
